-- Controlled smoke fixture (docs/FLUENCY_PRODUCTION_DEPLOYMENT.md §Smoke). Synthetic accounts only: smoke-fl-*@example.test.
-- psql variables: :'run' (short run tag), :'pw' (a random password generated by the caller, never stored or printed).
-- Creates: DM, player, stranger (email/password, confirmed); a campaign (DM = smoke DM, player member); one player character in
-- the campaign with a hidden condition and an unrevealed DM note; a second player character outside it. Removal:
-- smoke_cleanup.sql. Never touches any other row.
begin;
do $$
declare r text := current_setting('smoke.run'); pw text := current_setting('smoke.pw');
  u record; uid uuid; camp uuid := gen_random_uuid();
begin
  if r !~ '^[a-z0-9]{4,12}$' then raise exception 'bad run tag'; end if;
  for u in select * from (values ('dm'), ('player'), ('stranger')) v(kind) loop
    uid := gen_random_uuid();
    insert into auth.users (instance_id, id, aud, role, email, encrypted_password, email_confirmed_at, raw_app_meta_data,
      raw_user_meta_data, created_at, updated_at, confirmation_token, recovery_token, email_change_token_new, email_change,
      email_change_token_current, reauthentication_token, phone_change, phone_change_token)
    values ('00000000-0000-0000-0000-000000000000', uid, 'authenticated', 'authenticated', format('smoke-fl-%s-%s@example.test', u.kind, r),
      extensions.crypt(pw, extensions.gen_salt('bf')), now(), '{"provider":"email","providers":["email"]}', jsonb_build_object('full_name', 'Smoke ' || u.kind),
      now(), now(), '', '', '', '', '', '', '', '');
    insert into auth.identities (provider_id, user_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
    values (uid::text, uid, jsonb_build_object('sub', uid::text, 'email', format('smoke-fl-%s-%s@example.test', u.kind, r), 'email_verified', true),
      'email', now(), now(), now());
    perform set_config('smoke.' || u.kind, uid::text, true);
  end loop;
  insert into public.campaigns (id, name, description, created_by)
  values (camp, 'Smoke FL ' || r, 'synthetic smoke test campaign (removed after the test)', current_setting('smoke.dm')::uuid);
  insert into public.campaign_members (campaign_id, user_id, role) values
    (camp, current_setting('smoke.dm')::uuid, 'dm'), (camp, current_setting('smoke.player')::uuid, 'player');
  insert into public.characters (owner_id, name, campaign_id, level, hp_max, hp_current, strength, dexterity, constitution, intelligence, wisdom, charisma)
  values (current_setting('smoke.player')::uuid, 'Smoke FL Hero ' || r, camp, 1, 12, 12, 14, 12, 14, 10, 12, 8),
         (current_setting('smoke.player')::uuid, 'Smoke FL Solo ' || r, null, 1, 10, 10, 10, 14, 12, 10, 10, 12);
  insert into public.character_conditions (character_id, name, hidden, applied_by)
  select id, 'Smoke hidden curse', true, current_setting('smoke.dm')::uuid from public.characters where name = 'Smoke FL Hero ' || r;
  insert into public.dm_character_notes (character_id, campaign_id, author_id, title, body)
  select id, camp, current_setting('smoke.dm')::uuid, 'Smoke secret note', 'unrevealed' from public.characters where name = 'Smoke FL Hero ' || r;
end $$;
select 'smoke fixture', count(*) from auth.users where email like 'smoke-fl-%-' || current_setting('smoke.run') || '@example.test';
commit;
